    /// A real git repository (with an initial commit) for command tests.
    fn git_repo() -> PathBuf {
        let dir = std::env::temp_dir().join(format!("hanihi-cmd-{}", uuid::Uuid::new_v4()));
        std::fs::create_dir_all(dir.join("src")).unwrap();
        std::fs::write(
