    }

    // ── run_command ──

    fn argv(args: &[&str]) -> Vec<String> {
        args.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn command_allowlist_accepts_cargo_and_git() {
        for cmd in [
            argv(&["cargo", "check", "--workspace"]),
